  constructor() {
    this.heap = []; // heap[0] is the minimum
  }
  size() { return this.heap.length; }
  peek() { return this.heap[0]; }

  push(val) {
    this.heap.push(val);                 // add at the next free leaf
    this.siftUp(this.heap.length - 1);
  }

  pop() {
    const h = this.heap;
    const min = h[0];
    const last = h.pop();                // remove the last leaf
    if (h.length > 0) {
      h[0] = last;                       // move it to the root
      this.siftDown(0);
    }
    return min;
  }

  siftUp(i) {
    const h = this.heap;
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (h[parent] <= h[i]) break;      // heap order restored
      [h[parent], h[i]] = [h[i], h[parent]];
      i = parent;
    }
  }

  siftDown(i) {
    const h = this.heap;
    while (true) {
      const left = 2 * i + 1, right = 2 * i + 2;
      let smallest = i;
      if (left < h.length && h[left] < h[smallest]) smallest = left;
      if (right < h.length && h[right] < h[smallest]) smallest = right;
      if (smallest === i) break;         // both children are larger
      [h[i], h[smallest]] = [h[smallest], h[i]];
      i = smallest;
    }
  }
