class MinHeap {
    private final List<Integer> heap = new ArrayList<>(); // heap.get(0) is the minimum

    public int size() { return heap.size(); }
    public int peek() { return heap.get(0); }

    public void push(int val) {
        heap.add(val);                            // add at the next free leaf
        siftUp(heap.size() - 1);
    }

    public int pop() {
        int min = heap.get(0);
        int last = heap.remove(heap.size() - 1);  // remove the last leaf
        if (!heap.isEmpty()) {
            heap.set(0, last);                    // move it to the root
            siftDown(0);
        }
        return min;
    }

    private void siftUp(int i) {
        while (i > 0) {
            int parent = (i - 1) / 2;
            if (heap.get(parent) <= heap.get(i)) break; // heap order restored
            swap(parent, i);
            i = parent;
        }
    }

    private void siftDown(int i) {
        int n = heap.size();
        while (true) {
            int left = 2 * i + 1, right = 2 * i + 2, smallest = i;
            if (left < n && heap.get(left) < heap.get(smallest)) smallest = left;
            if (right < n && heap.get(right) < heap.get(smallest)) smallest = right;
            if (smallest == i) return;            // both children are larger
            swap(i, smallest);
            i = smallest;
        }
    }

    private void swap(int i, int j) {
        int tmp = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, tmp);
    }
}

