function mergeKLists(lists) {
  const heap = new Heap((a, b) => a.val < b.val);    // min-heap of current heads
  for (const head of lists) if (head) heap.push(head);
  const dummy = new ListNode(0);
  let tail = dummy;
  while (heap.size() > 0) {
    const node = heap.pop();                         // smallest head overall
    tail.next = node;
    tail = node;
    if (node.next) heap.push(node.next);             // its successor joins the heap
