  return dummy.next;
}

public ListNode mergeKLists(ListNode[] lists) {
    PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val));
    for (ListNode head : lists) if (head != null) heap.offer(head); // current heads
    ListNode dummy = new ListNode(0), tail = dummy;
    while (!heap.isEmpty()) {
        ListNode node = heap.poll();                    // smallest head overall
        tail.next = node;
        tail = node;
        if (node.next != null) heap.offer(node.next);   // its successor joins the heap
    }
    return dummy.next;
}

