function leastInterval(tasks, n) {
  const counts = new Map();
  for (const t of tasks) counts.set(t, (counts.get(t) || 0) + 1);
  const heap = new Heap((a, b) => a > b);   // max-heap of remaining counts
  for (const cnt of counts.values()) heap.push(cnt);
  const cooldown = [];                      // [remaining, timeReady], FIFO
  let time = 0;
  while (heap.size() > 0 || cooldown.length > 0) {
    time++;
    if (heap.size() > 0) {
      const left = heap.pop() - 1;          // run the most frequent task
      if (left > 0) cooldown.push([left, time + n]);
    }                                       // else: the CPU idles this slot
    if (cooldown.length > 0 && cooldown[0][1] === time) {
      heap.push(cooldown.shift()[0]);       // cooled down: ready again
    }
  }
  return time;
}

public int leastInterval(char[] tasks, int n) {
    int[] counts = new int[26];
    for (char t : tasks) counts[t - 'A']++;
    PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder()); // remaining counts
    for (int cnt : counts) if (cnt > 0) heap.offer(cnt);
    Deque<int[]> cooldown = new ArrayDeque<>();  // {remaining, timeReady}, FIFO
    int time = 0;
    while (!heap.isEmpty() || !cooldown.isEmpty()) {
        time++;
        if (!heap.isEmpty()) {
            int left = heap.poll() - 1;          // run the most frequent task
            if (left > 0) cooldown.offer(new int[] {left, time + n});
        }                                        // else: the CPU idles this slot
        if (!cooldown.isEmpty() && cooldown.peek()[1] == time) {
            heap.offer(cooldown.poll()[0]);      // cooled down: ready again
        }
    }
    return time;
}

function heapSort(arr) {
  const n = arr.length;
  // 1. build a max-heap bottom-up: sift down every internal node
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) siftDown(arr, i, n);
  // 2. move the max to the end, shrink the heap, repair the root
  for (let end = n - 1; end > 0; end--) {
    [arr[0], arr[end]] = [arr[end], arr[0]];
    siftDown(arr, 0, end);
  }
  return arr;
}

