public void heapSort(int[] arr) {
    int n = arr.length;
    for (int i = n / 2 - 1; i >= 0; i--) siftDown(arr, i, n); // 1. build a max-heap
    for (int end = n - 1; end > 0; end--) {
        swap(arr, 0, end);                // 2. move the max to the end
        siftDown(arr, 0, end);            //    and repair the smaller heap
    }
}

private void siftDown(int[] arr, int i, int size) {
    while (true) {
        int left = 2 * i + 1, right = 2 * i + 2, largest = i;
        if (left < size && arr[left] > arr[largest]) largest = left;
        if (right < size && arr[right] > arr[largest]) largest = right;
        if (largest == i) return;         // both children are smaller
        swap(arr, i, largest);
        i = largest;
    }
}

private void swap(int[] arr, int i, int j) {
    int tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
}

